using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
using MedGas2024.Core;
namespace MedGas2024.UI
{
    public sealed class LegacyMapForm : Form
    {
        readonly BindingList<LegacyMapRow> rows;readonly Func<IList<LegacyMapRow>,bool> inspectApply;readonly Func<bool> automatic;
        readonly DataGridView grid=new DataGridView{Name="LegacyMapGrid",Dock=DockStyle.Fill};readonly ComboBox layer=new ComboBox{Name="LegacyTargetLayer",DropDownStyle=ComboBoxStyle.DropDownList,Width=260};readonly ComboBox type=new ComboBox{Name="LegacyTargetType",DropDownStyle=ComboBoxStyle.DropDown,Width=280,AutoCompleteMode=AutoCompleteMode.SuggestAppend,AutoCompleteSource=AutoCompleteSource.ListItems};readonly CheckBox sync=new CheckBox{Name="LegacySyncLayer",Text="Đồng bộ linetype của Layer",AutoSize=true};readonly CheckBox copy=new CheckBox{Name="LegacyCopySource",Text="Sao chép R nguồn vào nét đích đã có",AutoSize=true};readonly Label status=new Label{Name="LegacyStatus",Dock=DockStyle.Fill};bool loading;
        public Action<Exception> ErrorHandler{get;set;}
        public LegacyMapForm(LegacyMapCatalog catalog,Func<IList<LegacyMapRow>,bool> apply,Func<bool> auto)
        {UiTheme.Attach(this);
            rows=new BindingList<LegacyMapRow>(catalog.Rows);inspectApply=apply;automatic=auto;Text="Mr.T Đối chiếu nét R mã về Layer / linetype | 2.0.2.7";Font=UiStyle.Body();StartPosition=FormStartPosition.CenterParent;AutoScaleMode=AutoScaleMode.Dpi;Size=new Size(1450,800);MinimumSize=new Size(1120,700);
            var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=1,RowCount=5};root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,42));root.RowStyles.Add(new RowStyle(SizeType.Absolute,45));Controls.Add(root);
            root.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Chọn một hoặc nhiều dòng nguồn, chọn Layer và linetype đích rồi bấm Gán đích. Có thể nhập tên linetype mới để sao chép nét R nguồn. Không tự tạo Layer.\r\nChỉ áp dụng các dòng được tích. Hai tùy chọn đồng bộ/ghi đè có thể ảnh hưởng đối tượng khác; luôn xem trước trước khi ghi."},0,0);
            UiStyle.Grid(grid);grid.AutoGenerateColumns=false;grid.RowHeadersVisible=false;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.MultiSelect=true;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;
            grid.Columns.Add(new DataGridViewCheckBoxColumn{Name="Use",DataPropertyName="Use",HeaderText="Dùng",FillWeight=36,MinimumWidth=45});foreach(var col in new[]{new[]{"Source","Linetype mã","150"},new[]{"Label","Chữ trên nét","95"},new[]{"Count","Số đường","55"},new[]{"CurrentLayers","Layer hiện tại","135"},new[]{"TargetLayer","Layer đích","135"},new[]{"TargetType","Linetype đích","145"},new[]{"State","Tình trạng","180"}})grid.Columns.Add(new DataGridViewTextBoxColumn{Name=col[0],DataPropertyName=col[0],HeaderText=col[1],ReadOnly=true,FillWeight=Int32.Parse(col[2]),MinimumWidth=55,SortMode=DataGridViewColumnSortMode.NotSortable});grid.DataSource=rows;root.Controls.Add(grid,0,1);
            var options=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};options.RowStyles.Add(new RowStyle(SizeType.Percent,50));options.RowStyles.Add(new RowStyle(SizeType.Percent,50));var line=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};line.Controls.Add(new Label{Text="Layer đích:",AutoSize=true,Margin=new Padding(2,8,4,0)});layer.Items.Add(LegacyMapCatalog.KeepLayer);layer.Items.AddRange(catalog.Layers.Cast<object>().ToArray());layer.SelectedIndex=0;line.Controls.Add(layer);line.Controls.Add(new Label{Text="Linetype đích:",AutoSize=true,Margin=new Padding(10,8,4,0)});type.Items.AddRange(catalog.Types.Cast<object>().ToArray());line.Controls.Add(type);var set=new Button{Name="LegacySetTarget",Text="Gán đích cho dòng chọn",AutoSize=true};set.Click+=delegate{Guard(SetTarget);};line.Controls.Add(set);options.Controls.Add(line,0,0);var line2=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};line2.Controls.Add(sync);line2.Controls.Add(copy);line2.Controls.Add(new Label{Text="Không tích: giữ định nghĩa và Layer; ống sẽ dùng ByLayer nếu trùng nét.",AutoSize=true,Margin=new Padding(12,5,0,0)});options.Controls.Add(line2,0,1);root.Controls.Add(options,0,2);status.ForeColor=Color.FromArgb(45,76,99);root.Controls.Add(status,0,3);
            var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var cancel=new Button{Name="LegacyCancel",Text="Đóng",AutoSize=true,DialogResult=DialogResult.Cancel};var review=new Button{Name="LegacyReview",Text="Xem trước / áp dụng",AutoSize=true};review.Click+=delegate{Guard(delegate{grid.EndEdit();if(inspectApply(rows.ToList())){DialogResult=DialogResult.OK;Close();}});};var old=new Button{Name="LegacyAutomatic",Text="Khôi phục tự động như cũ",AutoSize=true};old.Click+=delegate{Guard(delegate{if(automatic!=null&&automatic()){DialogResult=DialogResult.OK;Close();}});};buttons.Controls.Add(cancel);buttons.Controls.Add(review);buttons.Controls.Add(old);root.Controls.Add(buttons,0,4);CancelButton=cancel;
            grid.SelectionChanged+=delegate{if(loading||grid.CurrentRow==null)return;var r=grid.CurrentRow.DataBoundItem as LegacyMapRow;if(r==null)return;loading=true;try{layer.SelectedItem=layer.Items.Contains(r.TargetLayer)?r.TargetLayer:LegacyMapCatalog.KeepLayer;type.Text=r.TargetType??"";sync.Checked=r.SyncLayer;copy.Checked=r.CopySourceToExisting;}finally{loading=false;}};grid.CurrentCellDirtyStateChanged+=delegate{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};Shown+=delegate{if(grid.CurrentRow!=null){var r=grid.CurrentRow.DataBoundItem as LegacyMapRow;if(r!=null){layer.SelectedItem=LegacyMapCatalog.KeepLayer;type.Text=r.TargetType??"";}}};
        }
        void SetTarget()
        {
            grid.EndEdit();string target=(type.Text??"").Trim();if(target.Length==0)throw new ArgumentException("Chọn hoặc nhập linetype đích.");var selected=grid.SelectedRows.Cast<DataGridViewRow>().Select(x=>x.DataBoundItem as LegacyMapRow).Where(x=>x!=null).Distinct().ToArray();if(selected.Length==0)throw new ArgumentException("Chọn ít nhất một dòng nguồn.");foreach(var row in selected){row.TargetLayer=layer.Text;row.TargetType=target;row.SyncLayer=sync.Checked;row.CopySourceToExisting=copy.Checked;row.Use=true;row.State=(sync.Checked?"Đổi nét Layer; ":"")+(copy.Checked?"Ghi đè nét đích; ":"")+"Chờ xem trước";}rows.ResetBindings();status.Text="Đã gán đích cho "+selected.Length+" dòng. Bấm Xem trước / áp dụng để kiểm tra phạm vi.";
        }
        void Guard(Action action){try{action();}catch(Exception ex){status.Text=ex.Message;if(ErrorHandler!=null)ErrorHandler(ex);}}
    }
}
